<?php
declare(strict_types=1);
require_once __DIR__ . '/../../services/BookingImportExport.php';
require_once __DIR__ . '/../../config/Database.php';
$filters=['booking_id'=>!empty($_GET['booking_id'])?(int)$_GET['booking_id']:null,'search'=>trim((string)($_GET['search']??'')),'date_from'=>$_GET['date_from']??'','date_to'=>$_GET['date_to']??'','month'=>$_GET['month']??'','year'=>$_GET['year']??'','agent_id'=>$_GET['agent_id']??'','vendor_id'=>$_GET['vendor_id']??'','status'=>$_GET['status']??''];
$rows=BookingImportExport::queryExportRows($filters);
usort($rows, static fn($a,$b) => [$a['Booking Date'], $a['_id']] <=> [$b['Booking Date'], $b['_id']]);
$agencyName=Database::fetchValue("SELECT setting_value FROM system_settings WHERE setting_key='agency_name'") ?: 'Aeroheights Travels & Tours';
function escp($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function printDate($value):string{ $value=trim((string)($value??'')); if(preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$value,$m)){ $year=(int)$m[1]; if($year<100)$year+=2000; return sprintf('%02d-%02d-%04d',(int)$m[3],(int)$m[2],$year); } return $value; }
?>
