<?php if(!$rows): ?><tr><td colspan="12">No booking records found.</td></tr><?php else: foreach($rows as $i=>$r):
$visaBuy=(float)($r['Visa Buy Cost (SAR)']??0);$ticketBuy=(float)($r['Ticket Buy Cost (SAR)']??0);$visaSell=(float)($r['Visa Sell Price (SAR)']??0);$ticketSell=(float)($r['Ticket Sell Price (SAR)']??0);$category=($ticketBuy>0||$ticketSell>0)?(($visaBuy>0||$visaSell>0)?'Visa + Ticket':'Ticket'):'Visa';$buy=$visaBuy+$ticketBuy;$sell=$visaSell+$ticketSell;
